+    let mut h = History::default();
+    h.execute(&older, DeleteEntity::new(&older, "blank").expect("delete"));
+    assert_eq!(stock_chord(&older, "Stock"), Some(TIGHT));
+    for p in [a, b, c] {
+        let _ = std::fs::remove_file(p);
+    }
